现在我需要手动计算资源受限的调度。这是一个NP-hard问题，我需要找到一个最优或接近最优的调度。让我分析关键路径和资源约束。

首先计算不考虑资源的关键路径：

<tool_call>
<bash>
<arguments>
{"command": "python3 -c "
tasks = {
    'A': {'duration': 2, 'cpu': 2, 'mem': 4, 'deps': []},
    'B': {'duration': 2, 'cpu': 1, 'mem': 2, 'deps': []},
    'C': {'duration': 3, 'cpu': 3, 'mem': 4, 'deps': ['A']},
    'D': {'duration': 2, 'cpu': 2, 'mem': 3, 'deps': ['A']},
    'E': {'duration': 4, 'cpu': 4, 'mem': 6, 'deps': ['B', 'C']},
    'F': {'duration': 3, 'cpu': 3, 'mem': 4, 'deps': ['D']},
    'G': {'duration': 5, 'cpu': 5, 'mem': 8, 'deps': ['E', 'F']},
    'H': {'duration': 1, 'cpu': 1, 'mem': 2, 'deps': ['E']},
    'I': {'duration': 2, 'cpu': 2, 'mem': 2, 'deps': ['G', 'H']}
}

def forward_pass():
    earliest_start = {}
    earliest_finish = {}

    for task in ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I']:
        if not tasks[task]['deps']:
            earliest_start[task] = 0
            earliest_finish[task] = tasks[task]['duration']
        else:
            earliest_start[task] = max(earliest_finish[dep] for dep in tasks[task]['deps'])
            earliest_finish[task] = earliest_start[task] + tasks[task]['duration']

    return earliest_start, earliest_finish

def backward_pass(earliest_finish):
    latest_finish = {}
    latest_start = {}

    makespan = max(earliest_finish.values())

    for task in reversed(['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I']):
        # 找出哪些任务依赖此任务
        dependents = []
        for t, info in tasks.items():
            if task in info['deps']:
                dependents.append(t)

        if not dependents:
            latest_finish[task] = makespan
        else:
            latest_finish[task] = min(latest_start[d] for d in dependents)

        latest_start[task] = latest_finish[task] - tasks[task]['duration']

    return latest_start, latest_finish

es, ef = forward_pass()
ls, lf = backward_pass(ef)

print('最早开始/完成时间:')
for task in ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I']:
    print(f'{task}: ES={es[task]}, EF={ef[task]}')

print('\n最晚开始/完成时间:')
for task in ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I']:
    print(f'{task}: LS={ls[task]}, LF={lf[task]}')

print(f'\n不考虑资源的关键路径长度: {max(ef.values())}')

# 找出关键路径
critical_path = []
for task in ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I']:
    if es[task] == ls[task]:
        critical_path.append(task)

print(f'关键路径: {critical_path}')
""}
